public class WordSearcherTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) throws Exception {
        java.nio.file.Path dir = java.nio.file.Files.createTempDirectory("wordsearch");
        java.nio.file.Path f = dir.resolve("story.txt");
        try {
            java.util.List<String> lines = java.util.List.of(
                    "The cat sat on the mat.",
                    "CAT and dog and Cat!",
                    "concatenate cats category",
                    "",
                    "cat,cat;CAT");
            java.nio.file.Files.write(f, lines);
            try {
                check("count of cat (whole words, any case)", 6, WordSearcher.countWord(f, "cat"));
                check("count of dog", 1, WordSearcher.countWord(f, "dog"));
                check("count of mat", 1, WordSearcher.countWord(f, "mat"));
                check("cats does not include cat", 1, WordSearcher.countWord(f, "cats"));
                check("query in upper case", 6, WordSearcher.countWord(f, "CAT"));
                check("missing word", 0, WordSearcher.countWord(f, "zebra"));
            } catch (Exception e) {
                check("no unexpected exception", "none", e.getClass().getSimpleName());
            }
        } finally {
            java.nio.file.Files.deleteIfExists(f);
            java.nio.file.Files.deleteIfExists(dir);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

